const input = $input.first().json;

const total_leads = Number(input.total_leads) || 1;
const qualified_leads = Number(input.qualified_leads) || 0;
const viewings_completed = Number(input.viewings_completed) || 0;
const offers_received = Number(input.offers_received) || 1;
const offers_accepted = Number(input.offers_accepted) || 0;
const deals_closed = Number(input.deals_closed) || 1;
const total_closed_value = Number(input.total_closed_value) || 0;

const qualification_rate = parseFloat(((qualified_leads / total_leads) * 100).toFixed(2));
const viewing_conversion_rate = parseFloat(((viewings_completed / (qualified_leads || 1)) * 100).toFixed(2));
const offer_acceptance_rate = parseFloat(((offers_accepted / offers_received) * 100).toFixed(2));
const deal_conversion_rate = parseFloat(((deals_closed / total_leads) * 100).toFixed(2));
const average_deal_value = parseFloat((total_closed_value / deals_closed).toFixed(2));

return {
  json: {
    ...input,
    qualification_rate,
    viewing_conversion_rate,
    offer_acceptance_rate,
    deal_conversion_rate,
    average_deal_value,
    pipeline_value: Number(input.total_pipeline_value) || 0,
    closed_value: total_closed_value,
    average_response_time: Number(input.avg_response_time_minutes) || 0,
    follow_up_completion_rate: Number(input.follow_up_completion_rate) || 0
  }
};

const input = $input.first().json;

let score = 0;

// 1. Lead Quality (Max 20 points)
if (input.qualification_rate >= 50) score += 20;
else if (input.qualification_rate >= 35) score += 12;
else score += 5;

// 2. Conversion (Max 20 points)
if (input.deal_conversion_rate >= 5) score += 20;
else if (input.deal_conversion_rate >= 3) score += 12;
else score += 5;

// 3. Response Speed (Max 20 points)
if (input.average_response_time <= 10) score += 20;
else if (input.average_response_time <= 30) score += 12;
else score += 5;

// 4. Follow-up (Max 20 points)
if (input.follow_up_completion_rate >= 90) score += 20;
else if (input.follow_up_completion_rate >= 75) score += 12;
else score += 5;

// 5. Deal Performance / Offer Acceptance (Max 20 points)
if (input.offer_acceptance_rate >= 50) score += 20;
else if (input.offer_acceptance_rate >= 35) score += 12;
else score += 5;

let health_status = "CRITICAL";
if (score >= 80) {
  health_status = "HEALTHY";
} else if (score >= 60) {
  health_status = "NEEDS ATTENTION";
}

return {
  json: {
    ...input,
    business_health_score: score,
    business_health: health_status
  }
};

