const input = $input.first().json;
const risks = [];

if (input.qualification_rate < 50) {
  risks.push("Low lead qualification rate");
}
if (input.average_response_time > 10) {
  risks.push("Response time above target");
}
if (input.viewing_conversion_rate < 70) {
  risks.push("Low viewing conversion rate");
}
if (input.offer_acceptance_rate < 50) {
  risks.push("Offer acceptance rate needs improvement");
}
if (input.follow_up_completion_rate < 85) {
  risks.push("Follow-up completion rate low");
}
if (input.deal_conversion_rate < 5) {
  risks.push("Low overall deal conversion rate");
}

return {
  json: {
    ...input,
    risks: risks.length > 0 ? risks : ["General operational inefficiency detected"]
  }
};

