const input = $input.first().json;

return {
  json: {
    report_period: input.report_period || "August 2026",
    business_health_score: input.business_health_score,
    business_health: input.business_health,
    metrics: {
      total_leads: input.total_leads,
      qualified_leads: input.qualified_leads,
      qualification_rate: input.qualification_rate,
      viewings_scheduled: input.viewings_scheduled,
      viewings_completed: input.viewings_completed,
      viewing_conversion_rate: input.viewing_conversion_rate,
      offers_received: input.offers_received,
      offers_accepted: input.offers_accepted,
      offer_acceptance_rate: input.offer_acceptance_rate,
      deals_closed: input.deals_closed,
      deal_conversion_rate: input.deal_conversion_rate,
      pipeline_value: input.pipeline_value,
      closed_value: input.closed_value,
      average_deal_value: input.average_deal_value,
      average_response_time: input.average_response_time,
      follow_up_completion_rate: input.follow_up_completion_rate
    },
    risk_assessment: {
      status: input.status || (input.business_health === "HEALTHY" ? "HEALTHY" : "NEEDS_ATTENTION"),
      priority: input.priority || "LOW",
      action_required: input.action_required ?? false,
      risks: input.risks || [],
      recommended_actions: input.recommended_actions || []
    }
  }
};

const input = $input.first().json;
const m = input.metrics;

const pipelineFormatted = `$${(m.pipeline_value / 1000000).toFixed(2)}M`;
const closedFormatted = `$${(m.closed_value / 1000000).toFixed(2)}M`;

const summary = `Real estate operations processed ${m.total_leads} leads during ${input.report_period}. ${m.qualified_leads} leads qualified, generating ${m.viewings_completed} completed viewings and ${m.deals_closed} closed deals. Pipeline value reached ${pipelineFormatted} with ${closedFormatted} in closed value. Overall business health score is ${input.business_health_score} (${input.business_health}).`;

return {
  json: {
    ...input,
    executive_summary: summary
  }
};
